# backend/main.py
from fastapi import FastAPI, Depends, HTTPException, WebSocket, WebSocketDisconnect, BackgroundTasks
from fastapi.responses import JSONResponse
from fastapi.middleware.cors import CORSMiddleware
from sqlalchemy.orm import Session
from typing import List
import asyncio
from datetime import datetime, timezone

from .config import settings
from .database import SessionLocal, engine
from . import models, schemas, crud
from .logic import calculate_cpm, CPMTask
from .connection_manager import manager
from .orchestrator import run_simulation

# Create tables if they don't exist
models.Base.metadata.create_all(bind=engine)

app = FastAPI(
    title=settings.app_name,
    version=settings.app_version,
    description=settings.app_description,
    debug=settings.debug_mode,
)

# Allow local dev frontends
origins = [
    "http://localhost:5173",
    "http://127.0.0.1:5173",
    "http://localhost:3000",
    "http://127.0.0.1:3000",
]

app.add_middleware(
    CORSMiddleware,
    # allow_origins=origins,  <-- Replaced by regex below for better local dev support
    allow_origin_regex=r"http://(localhost|127\.0\.0\.1)(:\d+)?",
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


@app.on_event("startup")
def cleanup_stale_simulations():
    """
    On server startup, check for any simulations stuck in 'running' state
    (e.g. from a server crash or restart) and mark them as failed.
    """
    db = SessionLocal()
    try:
        stale_sims = db.query(models.SimulationRun).filter(models.SimulationRun.status == "running").all()
        if stale_sims:
            print(f"Startup: Found {len(stale_sims)} stale simulations. Marking them as failed.")
            for sim in stale_sims:
                sim.status = "failed"
                sim.completed_at = datetime.now(timezone.utc)
                # We could add a 'reason' to results if the schema allows, 
                # but simply failing them releases the UI from waiting.
            db.commit()
    except Exception as e:
        print(f"Startup: Error cleaning up stale simulations: {e}")
    finally:
        db.close()


# Dependency for DB session
def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()


@app.get("/", tags=["Health"])
async def root():
    return {"message": "FastAPI is running!"}


@app.get("/health", tags=["Health"])
async def health_check():
    return {"status": "ok", "version": settings.app_version}


# Project endpoints
@app.post("/projects/", response_model=schemas.Project, tags=["Projects"])
def create_project(project: schemas.ProjectCreate, db: Session = Depends(get_db)):
    return crud.create_project(db=db, project=project)


@app.get("/projects/", response_model=List[schemas.Project], tags=["Projects"])
def read_projects(skip: int = 0, limit: int = 100, db: Session = Depends(get_db)):
    return crud.get_projects(db, skip=skip, limit=limit)


@app.get("/projects/{project_id}", response_model=schemas.Project, tags=["Projects"])
def read_project(project_id: int, db: Session = Depends(get_db)):
    project = crud.get_project(db, project_id=project_id)
    if project is None:
        raise HTTPException(status_code=404, detail="Project not found")
    return project


@app.patch("/projects/{project_id}", response_model=schemas.Project, tags=["Projects"])
def update_project(project_id: int, project: schemas.ProjectUpdate, db: Session = Depends(get_db)):
    db_project = crud.get_project(db, project_id=project_id)
    if db_project is None:
        raise HTTPException(status_code=404, detail="Project not found")
    for var, value in project.model_dump(exclude_unset=True).items():
        setattr(db_project, var, value)
    db.add(db_project)
    db.commit()
    db.refresh(db_project)
    return db_project


@app.delete("/projects/{project_id}", tags=["Projects"])
def delete_project(project_id: int, db: Session = Depends(get_db)):
    db_project = crud.get_project(db, project_id=project_id)
    if db_project is None:
        raise HTTPException(status_code=404, detail="Project not found")
    db.delete(db_project)
    db.commit()
